import { NextResponse, type NextRequest } from "next/server";
import { createServerClient } from "@/lib/supabase";
import { verifySecret } from "@/lib/auth";
import { WORKOUT_ID_RE } from "@/lib/workout-id";
import { teacherFromRequest } from "@/lib/teacher-auth";

// File (or unfile) a workout under one of the teacher's labeled classes. The
// teacher must own the class, and the workout must be theirs to see: generated
// in one of their classes, or generated by them.
export async function POST(request: NextRequest) {
  if (!verifySecret(request)) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  const { teacher, withCookies } = await teacherFromRequest(request);
  if (!teacher) return NextResponse.json({ error: "Sign in with your Mitty teacher account first." }, { status: 401 });

  const body = await request.json().catch(() => ({}));
  const code = typeof body.code === "string" ? body.code.toUpperCase() : "";
  const workoutId = typeof body.workoutId === "string" ? body.workoutId.toUpperCase() : "";
  if (!/^[A-Z0-9]{6}$/.test(code) || !WORKOUT_ID_RE.test(workoutId)) {
    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  }

  const supabase = createServerClient();
  const { data: cls } = await supabase.from("pe_classes").select("id, owner_id").eq("code", code).maybeSingle();
  if (!cls || cls.owner_id !== teacher.id) return NextResponse.json({ error: "Not your class." }, { status: 404 });

  const { data: w } = await supabase.from("workouts").select("class_code, created_by").eq("id", workoutId).maybeSingle();
  if (!w) return NextResponse.json({ error: "Workout not found." }, { status: 404 });
  if (w.created_by !== teacher.id) {
    const { data: home } = await supabase.from("pe_classes").select("owner_id").eq("code", w.class_code).maybeSingle();
    if (home?.owner_id !== teacher.id) return NextResponse.json({ error: "Workout not found." }, { status: 404 });
  }

  const { error } = body.filed === false
    ? await supabase.from("class_workouts").delete().eq("class_id", cls.id).eq("workout_id", workoutId)
    : await supabase.from("class_workouts").upsert(
        { class_id: cls.id, workout_id: workoutId, added_by: teacher.id },
        { onConflict: "class_id,workout_id" }
      );
  if (error) {
    console.error("class-workouts error:", error);
    return NextResponse.json({ error: "Couldn't update filing." }, { status: 500 });
  }
  return withCookies(NextResponse.json({ ok: true, filed: body.filed !== false }));
}
